<?php require_once '../config.php'; requireLogin(); header('Content-Type: application/json; charset=utf-8');try{$t=getAccessToken();$id=(int)($_GET['id']??0);if($id){$c=sb_query('collections',['select'=>'id,name,description,type,cover_image,cover_color,total_words,video_url,pdf_url','id'=>'eq.'.$id,'limit'=>1],$t);if(!$c)throw new RuntimeException('مجموعه پیدا نشد');$chap=sb_query('collection_stories',['select'=>'chapter_number,chapter_title,content','collection_id'=>'eq.'.$id,'order'=>'chapter_number.asc','limit'=>100],$t);echo json_encode(['success'=>true,'collection'=>$c[0]+['chapters'=>$chap]],JSON_UNESCAPED_UNICODE);exit;}$cs=sb_query('collections',['select'=>'id,name,description,type,cover_image,cover_color,total_words,video_url,pdf_url','order'=>'created_at.desc','limit'=>100],$t);echo json_encode(['success'=>true,'collections'=>$cs],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(400);echo json_encode(['success'=>false,'error'=>sb_error_message($e)],JSON_UNESCAPED_UNICODE);}